using System;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;

namespace Cidonix.UniBridge.MCP.Editor.ToolRegistry
{
    // Concrete authoring producers, including recursive Animator snapshots and reviewed audit detail variants.
    // AuthoredJsonValue is limited to the optional authored Input Actions file JSON, never named business fields.
    internal static class AuthoringActionOutputRules
    {
        internal static Dictionary<string, JObject> Build(string owner)
        {
            var table = JObject.Parse(Contracts);
            if (!(table["owners"]?[owner] is JObject cases)) throw new ArgumentOutOfRangeException(nameof(owner), owner, "Unknown output contract owner.");
            var result = new Dictionary<string, JObject>(StringComparer.Ordinal);
            foreach (var action in cases.Properties())
            {
                var schema = (JObject)action.Value.DeepClone();
                schema["$defs"] = table["definitions"].DeepClone();
                result.Add(action.Name, schema);
            }
            if (owner == "UniBridge_ManageUI")
            {
                var eventSystem = (JObject)table["definitions"]["Authoring_UI_1562b4a49914748f"]["properties"]["eventSystem"].DeepClone();
                var mode = ActionOutputSchema.Enum("Old", "New", "Both");
                var actual = ActionOutputSchema.Success(ActionOutputSchema.Obj(
                    ("created", ActionOutputSchema.Type("boolean")),
                    ("repaired", ActionOutputSchema.Type("boolean")),
                    ("eventSystem", eventSystem),
                    ("inputBackend", mode),
                    ("inputModule", ActionOutputSchema.Type("string"))));
                var dryRun = ActionOutputSchema.Success(ActionOutputSchema.Obj(
                    ("created", ActionOutputSchema.Type("boolean")),
                    ("name", ActionOutputSchema.Type("string")),
                    ("inputBackend", mode),
                    ("inputModule", ActionOutputSchema.Type("string"))));
                var schema = ActionOutputSchema.AnyOf(actual, dryRun, ActionOutputSchema.Error());
                schema["$defs"] = table["definitions"].DeepClone();
                result["EnsureEventSystem"] = schema;
            }
            return result;
        }

